 async function graphicEntries(){const out=[];for(const[n,u]of[['store-graphics/google-feature-graphic-chosen.png',featureFile(proof.choice.feature)],['store-graphics/google-feature-graphic-alternate.png',featureFile(proof.choice.feature==='light'?'feature':'light')]])try{const r=await fetch('./'+u+'?v=2-8-7');if(r.ok)out.push({name:n,data:await r.arrayBuffer()})}catch{}return out}
